CREATE TABLE "production"."TT_DANDORI" (
	"INT_ID" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "production"."TT_DANDORI_INT_ID_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"INT_PLANT_ID" bigint NOT NULL,
	"INT_LINE_ID" bigint NOT NULL,
	"CHR_STATUS" varchar(32) NOT NULL,
	"INT_PART_ID" bigint,
	"INT_TOOLING_ID" bigint,
	"CHR_KODE_DANDORI" varchar(255),
	"CHR_KODE_SAMPLE" varchar(255),
	"INT_LINE_STOP_ID" bigint,
	"DTM_MULAI" timestamp with time zone NOT NULL,
	"DTM_START" timestamp with time zone,
	"DTM_SELESAI" timestamp with time zone,
	"INT_USER_MULAI_ID" bigint,
	"INT_USER_START_ID" bigint,
	"DTM_CREATED_AT" timestamp with time zone DEFAULT now() NOT NULL,
	"DTM_UPDATED_AT" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "TT_DANDORI_CHR_STATUS_CHK" CHECK ("production"."TT_DANDORI"."CHR_STATUS" IN ('DANDORI', 'BERJALAN', 'SELESAI'))
);
