-- Alasan berhenti DANDORI untuk pabrik yang belum punya; tombol DANDORI di stasiun membukanya.
INSERT INTO "production"."TM_STOP_REASON" ("INT_PLANT_ID", "CHR_CODE", "CHR_NAME", "CHR_CATEGORY", "FLG_IS_PLANNED", "INT_SORT_ORDER", "FLG_IS_ACTIVE")
SELECT p."INT_ID", 'STP-04', 'DANDORI', 'CHANGEOVER', true, 4, true
FROM "org"."TM_PLANT" p
WHERE NOT EXISTS (
  SELECT 1 FROM "production"."TM_STOP_REASON" r
  WHERE r."INT_PLANT_ID" = p."INT_ID" AND (r."CHR_CATEGORY" = 'CHANGEOVER' OR r."CHR_CODE" = 'STP-04')
);
